    import re
    import asyncio
    from decimal import Decimal, ROUND_HALF_UP

    # There are no knowledge_base helper functions available for this task, so none are used.

    def parse_price(text: str) -> Decimal:
        if not text:
            return Decimal('0.00')
        s = str(text)
        cleaned = re.sub(r"[^0-9.\-]", "", s)
        if cleaned == "":
            return Decimal('0.00')
        # If more than one dot, keep last as decimal separator
        if cleaned.count('.') > 1:
            parts = cleaned.split('.')
            cleaned = ''.join(parts[:-1]) + '.' + parts[-1]
        try:
            return Decimal(cleaned)
        except Exception:
            return Decimal('0.00')

    def format_price(d: Decimal) -> str:
        return str(d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

    # Ensure page is settled
    try:
        await page.wait_for_load_state('networkidle')
    except Exception:
        await asyncio.sleep(1)

    # Defensive attempt to close obvious modal/popups by clicking buttons whose name suggests close
    try:
        all_buttons = page.get_by_role('button')
        try:
            btn_count = await all_buttons.count()
        except Exception:
            btn_count = 0
        for bi in range(btn_count):
            try:
                btn = all_buttons.nth(bi)
                name = ''
                try:
                    name = (await btn.get_attribute('aria-label')) or ''
                except Exception:
                    name = ''
                if not name:
                    try:
                        name = (await btn.inner_text()) or ''
                    except Exception:
                        name = ''
                lname = name.strip().lower()
                if 'close' in lname or lname in ('×', 'x', '✕'):
                    try:
                        await btn.click()
                        await asyncio.sleep(0.3)
                    except Exception:
                        pass
            except Exception:
                continue
    except Exception:
        pass

    # Go to Manage Products grid (relative)
    try:
        await page.goto('/index.php/admin/catalog_product/')
        await page.wait_for_load_state('networkidle')
    except Exception:
        # continue even if navigation fails
        pass

    # Collect candidate product edit links by scanning rows' text
    candidate_hrefs = []
    try:
        rows = page.get_by_role('row')
        try:
            total_rows = await rows.count()
        except Exception:
            total_rows = 0
        for i in range(total_rows):
            try:
                row = rows.nth(i)
            except Exception:
                continue
            # Only consider rows that contain an Edit link
            try:
                edit_links = row.get_by_role('link', name='Edit')
                edit_link_count = 0
                try:
                    edit_link_count = await edit_links.count()
                except Exception:
                    edit_link_count = 0
                if edit_link_count == 0:
                    continue
            except Exception:
                continue
            try:
                row_text = (await row.inner_text() or '').lower()
            except Exception:
                row_text = ''
            if 'desiree' in row_text and 'black' in row_text and 'xs' in row_text:
                try:
                    href = await edit_links.nth(0).get_attribute('href')
                except Exception:
                    href = None
                if href and href not in candidate_hrefs:
                    candidate_hrefs.append(href)
    except Exception:
        pass

    # If nothing found, nothing to do
    if not candidate_hrefs:
        return

    # Iterate candidate edit pages and update price
    for href in candidate_hrefs:
        try:
            # Navigate to product edit page
            await page.goto(href)
            try:
                await page.wait_for_load_state('networkidle')
            except Exception:
                await asyncio.sleep(0.5)

            price_field = None
            current_price_text = None

            # Try a set of locator strategies in order
            locator_factories = [
                lambda: page.get_by_role('spinbutton', name='Price'),
                lambda: page.get_by_role('textbox', name='Price'),
                lambda: page.get_by_label('Price'),
                lambda: page.get_by_role('spinbutton'),
                lambda: page.get_by_role('textbox')
            ]

            for factory in locator_factories:
                loc = None
                try:
                    loc = factory()
                except Exception:
                    loc = None
                if loc is None:
                    continue
                try:
                    c = await loc.count()
                except Exception:
                    c = 0
                if c <= 0:
                    continue
                try:
                    fld = loc.nth(0)
                except Exception:
                    continue
                # Try to read value
                val = None
                try:
                    val = await fld.input_value()
                except Exception:
                    try:
                        val = await fld.get_attribute('value')
                    except Exception:
                        val = None
                price_field = fld
                current_price_text = val
                if current_price_text:
                    break

            # If still no value, scrape page text for currency-like pattern
            if not current_price_text:
                try:
                    doc = page.get_by_role('document')
                    page_text = ''
                    try:
                        if await doc.count() > 0:
                            page_text = await doc.nth(0).inner_text()
                        else:
                            page_text = await page.inner_text()
                    except Exception:
                        page_text = await page.inner_text()
                except Exception:
                    try:
                        page_text = await page.inner_text()
                    except Exception:
                        page_text = ''
                m = re.search(r"\$?\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]+)?)", page_text)
                if m:
                    current_price_text = m.group(0)

            if not current_price_text:
                # cannot determine current price; skip this product
                continue

            # Parse and compute new price
            cur = parse_price(current_price_text)
            new_price = (cur * Decimal('1.37')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            new_price_str = format_price(new_price)

            filled = False
            if price_field is not None:
                try:
                    await price_field.fill(new_price_str)
                    filled = True
                except Exception:
                    try:
                        await price_field.evaluate('(el, v) => el.value = v', new_price_str)
                        filled = True
                    except Exception:
                        filled = False

            # If couldn't fill via the located field, try to fill any textbox on the page
            if not filled:
                txts = None
                try:
                    txts = page.get_by_role('textbox')
                    tcount = 0
                    try:
                        tcount = await txts.count()
                    except Exception:
                        tcount = 0
                except Exception:
                    txts = None
                    tcount = 0
                for k in range(tcount):
                    try:
                        candidate = txts.nth(k)
                        try:
                            await candidate.fill(new_price_str)
                            filled = True
                            break
                        except Exception:
                            try:
                                await candidate.evaluate('(el, v) => el.value = v', new_price_str)
                                filled = True
                                break
                            except Exception:
                                continue
                    except Exception:
                        continue

            # Click Save using accessible button if present
            try:
                save_btn = page.get_by_role('button', name='Save')
                try:
                    sc = await save_btn.count()
                except Exception:
                    sc = 0
                if sc > 0:
                    await save_btn.nth(0).click()
                    try:
                        await page.wait_for_load_state('networkidle')
                    except Exception:
                        await asyncio.sleep(1)
                else:
                    # fallback: find any button containing 'save' in its accessible name/text
                    all_btns = page.get_by_role('button')
                    try:
                        bc = await all_btns.count()
                    except Exception:
                        bc = 0
                    for b in range(bc):
                        try:
                            btn = all_btns.nth(b)
                            name = ''
                            try:
                                name = (await btn.get_attribute('aria-label')) or ''
                            except Exception:
                                name = ''
                            if not name:
                                try:
                                    name = (await btn.inner_text()) or ''
                                except Exception:
                                    name = ''
                            if 'save' in name.lower():
                                await btn.click()
                                try:
                                    await page.wait_for_load_state('networkidle')
                                except Exception:
                                    await asyncio.sleep(1)
                                break
                        except Exception:
                            continue
            except Exception:
                pass

            await asyncio.sleep(0.6)

            # Return to product grid to continue with next product
            try:
                await page.goto('/index.php/admin/catalog_product/')
                try:
                    await page.wait_for_load_state('networkidle')
                except Exception:
                    await asyncio.sleep(0.5)
            except Exception:
                pass

        except Exception:
            # continue to next candidate on any failure
            continue

